<script setup lang="ts">
import {computed,ref,onMounted,onUnmounted} from 'vue';import {transport,type CaptureStatus} from './transport.ts';import type {UsageSummary} from '../usage/reader.ts';
defineProps<{status:CaptureStatus|null}>();const usage=ref<UsageSummary|null>(null),error=ref(''),provider=ref('all');let timer:ReturnType<typeof setInterval>|undefined;
const key=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=key(new Date()),month=today.slice(0,7);const monday=new Date();monday.setDate(monday.getDate()-(monday.getDay()+6)%7);const week=key(monday);
const number=(n:number)=>Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n);
const money=(n:number)=>Intl.NumberFormat('en',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const rows=computed(()=>usage.value?.days.filter(d=>provider.value==='all'||d.provider===provider.value)||[]);
const total=(start:string,end?:string)=>rows.value.filter(d=>d.date>=start&&(!end||d.date<=end)).reduce((a,d)=>({tokens:a.tokens+d.tokens,usd:a.usd+d.usd,unpriced:a.unpriced+d.unpriced}),{tokens:0,usd:0,unpriced:0});
const periods=computed(()=>[{title:'Today',...total(today,today)},{title:'This week',...total(week,today)},{title:'This month',...total(month+'-01',today)}]);
const days=computed(()=>Array.from({length:new Date().getDate()},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0');const entries=rows.value.filter(d=>d.date===date);return {date,day:i+1,tokens:entries.reduce((a,d)=>a+d.tokens,0),usd:entries.reduce((a,d)=>a+d.usd,0)};}));
const peak=computed(()=>Math.max(1,...days.value.map(d=>d.tokens)));
const breakdown=computed(()=>rows.value.filter(d=>d.date===today).reduce((a,d)=>({input:a.input+d.counts.input,output:a.output+d.counts.output,read:a.read+d.counts.cacheRead,write:a.write+d.counts.cacheWrite,reasoning:a.reasoning+d.counts.reasoning}),{input:0,output:0,read:0,write:0,reasoning:0}));
const models=computed(()=>usage.value?.models.filter(m=>provider.value==='all'||m.provider===provider.value)||[]);
const limits=computed(()=>usage.value?.limits.filter(l=>provider.value==='all'||l.provider===provider.value)||[]);
const time=(n:number|null)=>n?new Date(n).toLocaleString('en',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Unknown';
async function refresh(){try{usage.value=await transport.usage();error.value='';}catch(e){error.value=String(e);}}
onMounted(()=>{void refresh();timer=setInterval(()=>{void refresh();},5000);});onUnmounted(()=>clearInterval(timer));
</script>
<template>
<section class="usage-page"><div class="usage-heading"><div><h1>Tokens &amp; limits</h1><p>Usage from sessions captured by Agent Time.</p></div><select v-model="provider" aria-label="Filter usage provider"><option value="all">All providers</option><option value="claude">Claude</option><option value="codex">Codex</option></select></div>
<p v-if="!status?.surfaces.tokenUsage||(status&&!status.surfaces.claudeTokenUsage&&!status.surfaces.codexTokenUsage)" class="usage-notice">Token scanning is disabled. Enable token usage in Settings → Agents to update this history.</p><p v-if="error||usage?.error" class="usage-notice">{{error||usage?.error}}</p>
<div class="usage-metrics"><article v-for="period in periods" :key="period.title"><small>{{period.title}}’s tokens</small><strong>{{number(period.tokens)}}</strong><span>{{money(period.usd)}} <small>API equivalent{{period.unpriced?' · priced portion':''}}</small></span></article></div>
<div class="usage-panel"><div class="usage-panel-title"><h2>Daily usage this month</h2><small>{{usage?.scanning?`Reading history · ${usage.filesScanned} files checked`:`Updated ${usage?.lastScan?time(usage.lastScan*1000):'not yet'}`}}</small></div><div class="usage-chart"><div v-for="d in days" :key="d.date" class="usage-chart-column" :title="`${d.date}: ${d.tokens.toLocaleString()} tokens · ${money(d.usd)} API equivalent`"><div :class="['usage-chart-bar',{today:d.date===today}]" :style="{height:`${Math.max(2,d.tokens/peak*100)}%`}"></div><small>{{d.day}}</small></div></div><div class="usage-breakdown"><span>Today’s breakdown</span><dl><div><dt>Input</dt><dd>{{number(breakdown.input)}}</dd></div><div><dt>Output</dt><dd>{{number(breakdown.output)}}</dd></div><div><dt>Cache write</dt><dd>{{number(breakdown.write)}}</dd></div><div><dt>Cache read</dt><dd>{{number(breakdown.read)}}</dd></div></dl><small>Reasoning: {{number(breakdown.reasoning)}} · already included in output</small></div></div>
<div class="usage-panel"><div class="usage-panel-title"><h2>Account limits</h2><small>Shared across all sessions · reported by Orca</small></div><article v-for="(limit,index) in limits" :key="limit.provider+limit.accountId" class="limit-account"><div class="limit-heading"><strong>{{limit.provider==='claude'?'Claude':'Codex'}} · {{limit.accountId==='default'?'Default account':`Account ${index+1}`}}</strong><small>{{limit.status}} · updated {{time(limit.updatedAt)}}{{limit.updatedAt&&Date.now()-limit.updatedAt>900000?' · stale':''}}</small></div><div v-for="[name,window] in [['Session',limit.session],['Weekly',limit.weekly]]" :key="name" class="limit-window"><span>{{name}}</span><template v-if="window"><div class="limit-track"><i :style="{width:window.usedPercent+'%'}"></i></div><strong>{{Math.round(100-window.usedPercent)}}% remaining</strong><small>Resets {{time(window.resetsAt)}}</small></template><small v-else>Not reported</small></div></article><p v-if="!limits.length" class="usage-empty">No account limits have been received yet.</p></div>
<div class="usage-panel"><div class="usage-panel-title"><h2>Models this month</h2></div><table><thead><tr><th>Model</th><th>Tokens</th><th>API equivalent</th></tr></thead><tbody><tr v-for="m in models" :key="m.provider+m.model"><td>{{m.model}}</td><td>{{number(m.tokens)}}</td><td>{{m.unpriced?'Unavailable':money(m.usd)}}</td></tr></tbody></table></div>
<p v-if="usage?.pricing.error" class="usage-notice">Pricing update failed: {{usage.pricing.error}}. Keeping the last valid rates.</p>
<p class="usage-footnote">API equivalent is a standard, short-context, global pricing estimate in USD, not a subscription bill. Long context, speed tiers, region, and tool fees can differ. Unknown models remain unpriced. New usage uses rates verified {{usage?.pricingCheckedAt}}{{usage?.pricing.stale?' · verification overdue':''}}. Earlier estimates retain their imported pricing version. {{usage?.pricing.configured?'Updates checked daily while capture is enabled.':'Using bundled rates; update URL not configured.'}} · <a v-for="(source,index) in usage?.pricingSources" :key="source" :href="source" target="_blank" rel="noreferrer">{{index===0?'OpenAI':'Anthropic'}} </a></p>
</section>
</template>
<style scoped>
.usage-page{padding:30px 32px;overflow:auto;flex:1}.usage-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.usage-heading h1{font-size:25px;letter-spacing:-.6px;margin:0 0 8px}.usage-heading p{color:var(--muted);margin:0}select{border:1px solid var(--border);border-radius:6px;padding:7px;color:var(--text);background:var(--panel)}.usage-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:22px}.usage-metrics article,.usage-panel{background:var(--panel);border:1px solid var(--border);border-radius:10px}.usage-metrics article{padding:20px;display:flex;flex-direction:column;gap:8px}.usage-metrics strong{font-size:32px;letter-spacing:-1px}.usage-metrics small,.usage-panel small{color:var(--muted);font-size:11px}.usage-panel{margin-bottom:20px;overflow:hidden}.usage-panel-title{display:flex;justify-content:space-between;align-items:center;padding:18px 20px}.usage-panel-title h2{font-size:13px;margin:0}.usage-chart{height:150px;display:flex;gap:4px;padding:5px 20px 25px;margin-bottom:12px}.usage-chart-column{flex:1;height:100%;display:flex;justify-content:flex-end;flex-direction:column;position:relative}.usage-chart-bar{background:#808895;border-radius:3px 3px 0 0;min-height:2px}.usage-chart-bar.today{background:var(--blue)}.usage-chart-column small{position:absolute;bottom:-22px;width:100%;text-align:center;font-size:9px}.usage-breakdown{border-top:1px solid var(--border);padding:16px 20px}.usage-breakdown>span{font-size:12px;font-weight:600}.usage-breakdown dl{display:grid;grid-template-columns:repeat(4,1fr);margin:12px 0;gap:14px}.usage-breakdown dt{font-size:10px;color:var(--muted)}.usage-breakdown dd{margin:5px 0;font-size:16px;font-weight:600}.limit-account{padding:16px 20px;border-top:1px solid var(--border)}.limit-heading{display:flex;justify-content:space-between;margin-bottom:14px}.limit-window{display:flex;align-items:center;gap:12px;margin:10px 0;font-size:11px}.limit-window>span{width:52px}.limit-window strong{font-size:11px;font-weight:500;min-width:95px}.limit-track{height:5px;width:150px;background:var(--border);border-radius:5px;overflow:hidden}.limit-track i{display:block;height:100%;background:var(--blue)}table{width:100%;border-collapse:collapse}th,td{padding:12px 20px;text-align:left;border-top:1px solid var(--border);font-size:11px}th{color:var(--muted);font-weight:500}.usage-footnote,.usage-empty{color:var(--muted);font-size:11px;line-height:1.6}.usage-empty{padding:0 20px 16px}.usage-footnote a{color:var(--blue)}.usage-notice{padding:12px;background:var(--hover);font-size:12px;border-radius:7px}
</style>
